def lookup(item_id):
    if not isinstance(item_id, str) or item_id not in {"guide", "faq"}:
        raise ValueError("Unknown item")
    return {"id": item_id, "text": "Owned example"}
TOOLS = {"lookup": lookup}

def lookup(item_id):
    if item_id not in {"guide", "faq"}:
        raise ValueError("Unknown item")
    return {"id": item_id, "text": "Owned example"}

TOOLS = {"lookup": lookup}

def run(script, limit=3):
    events = []
    for call in script[:limit]:
        if call["name"] not in TOOLS:
            raise ValueError("Unknown tool")
        events.append(TOOLS[call["name"]](**call["arguments"]))
    return events

calls = [{"name": "lookup", "arguments": {"item_id": "guide"}}]
assert run(calls) == [{"id": "guide", "text": "Owned example"}]

def may_write(call, approved_ids):
    return call["action_id"] in approved_ids
call = {"action_id": "owned-example-1"}
assert not may_write(call, set())
assert may_write(call, {"owned-example-1"})
